(() => {
'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={plus:'M12 5v14M5 12h14',send:'m4 12 16-8-6 16-3-7-7-1Z M11 13l9-9',arrow:'M5 12h14m-6-6 6 6-6 6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',back:'m14 6-6 6 6 6'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]}"/></svg>`;
const num=v=>v==null?'—':Number(v).toFixed(3), date=v=>new Date(v).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
let local=false,configured=false,projects=[],p=null,view='overview',chatDraft='',selectedDetail=null,poll=null,busy=false;
let autoDemo=null;
let researchCases={};
const referenceLabel=()=>p?.research_context?.label||'历史实测';
const candidateName=c=>c?.features?.formula||c?.name||'';
let lastSurface="",lastMessageCount=0,lastProgress=0,lastSelection="",lastOperation="";
const reducedMotion=()=>matchMedia("(prefers-reduced-motion: reduce)").matches;
const views={engine:'资料与模型引擎',evidence:'文献与实验数据',overview:'研究工作区',data:'数据与候选',plan:'实验计划',results:'实验结果',report:'研究报告'};
function rich(text){return esc(text).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noreferrer">$1</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
async function api(path,body){if(window.AmadeusDemo)return window.AmadeusDemo.api(path,body);const response=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const data=await response.json();if(!response.ok)throw Error(data.error||'请求未完成');return data;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500);}
const running=()=>p?.operation.status==='running';
const known=()=>Object.fromEntries((p?.analysis?.candidates||[]).map(c=>[c.id,c]));
const done=()=>new Set((p?.measurements||[]).filter(m=>m.status==='completed'&&m.analysis_id===p?.analysis?.id).map(m=>m.candidate_id));
const predictionLabel=a=>a.task==='classification'?'P('+a.positive+')':a.metric;
const plan=()=>p?.plans.filter(x=>x.round===p.round).at(-1);
function side(){return `<aside class="side"><a href="./" class="brand" aria-label="Amadeus 首页"><img class="brand-logo" src="./logo.svg" alt="Amadeus" width="1968" height="382"></a><p class="side-caption">科研助手 · 实验决策</p><button class="new-project" data-do="home">＋ 新研究项目</button><nav aria-label="项目导航">${p?Object.entries(views).map(([k,v])=>`<button data-view="${k}" class="${view===k?'active':''}">${v}</button>`).join(''):'<button class="active">我的研究</button>'}</nav><div class="side-bottom"><span>${window.AmadeusDemo?'在线演示 · 公开研究案例':local?'本机工作台 · '+(configured?'DeepSeek 已连接':'待配置 DeepSeek'):'共享案例展示'}</span><a href="./classic.html" target="_blank">查看完整案例对照</a><a href="https://github.com/nighty35628/ligand-screening" target="_blank" rel="noreferrer">代码与运行说明</a></div></aside>`;}
function home(){return `<main id="main" class="home"><div class="home-intro"><div><h1>今天想推进什么研究？</h1><p>说说你的目标，带上已有数据，一起安排下一步实验。</p></div><img class="intro-mark" src="./mark.svg" alt="" width="96" height="96" aria-hidden="true"></div>
<form id="new-form" class="composer-home"><textarea id="new-goal" aria-label="描述研究问题" placeholder="例如：我想提高纳米晶的发光表现，这一轮最多测试3种配体。"></textarea><div class="composer-bottom"><small>目标、实验条件或一个待解决的问题，都可以从这里开始。</small><button class="btn primary" ${!local?'disabled':''}>开始研究 ${icon('arrow')}</button></div></form>
${!local?`<div class="offline">这里提供完整案例回放。<a href="http://127.0.0.1:8787/">打开本机工作台</a>，即可对话、上传数据和保存研究项目。</div>`:''}
<div class="case-row"><section class="case-feature"><div><h2>纳米晶发光优化</h2><p>公开实测案例 · 18种候选配体<br>从文献与实验数据，走到候选推荐和结果对照。</p><button class="btn primary" data-do="auto-demo">选择这个研究</button></div><img class="case-structure" src="./case-molecule.svg" alt="案例中的配体分子结构"></section><section class="research-examples" aria-label="材料研究案例">${Object.entries(researchCases).map(([id,c])=>`<article class="research-example"><div><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><small>${esc(c.detail)} · ${esc(c.label)}</small></div><button class="btn" data-case="${id}" aria-label="选择这个研究：${esc(c.title)}">选择这个研究</button></article>`).join('')}</section></div>
<div class="entry-list custom-entry"><button data-do="csv-project" ${!local?'disabled':''}><strong>从自己的实验数据开始</strong><small>上传历史数据和候选表，比较模型并安排测试。</small></button><button data-do="literature-project" ${!local?'disabled':''}><strong>先查资料，形成研究思路</strong><small>结合公开研究，整理可执行的实验行动。</small></button></div>
<section><div class="section-title"><h2>最近的研究</h2><small>${projects.length} 个项目</small></div>${projects.length?projects.map(x=>`<button class="recent-row" data-project="${x.id}"><div><strong>${esc(x.title)}</strong><small>${esc(x.task.goal||'继续补充研究目标')}</small></div><small>第 ${x.round} 轮<br>${date(x.updated)}</small></button>`).join(''):'<p class="empty">创建第一个项目，研究记录会保存在这里。</p>'}</section></main>`;}
function chat(){return `<section class="conversation" aria-label="研究对话"><div class="chat-heading">${icon('spark')}<strong>与 Amadeus 一起研究</strong></div><div class="messages" id="messages">${projectContext()?'<article class="message user"><div class="role">你</div><p>'+esc(openingQuestion)+'</p></article><article class="message assistant"><div class="role">Amadeus</div><p>先把性能指标、实验条件和数据对应关系整理清楚。本轮使用可对齐的相对发光数据筛选配体，PLQY保留为独立研究任务。</p></article>':''}${p.messages.length?p.messages.map(m=>`<article class="message ${m.role}"><div class="role">${m.role==='user'?'你':'Amadeus'}</div><p>${rich(m.content)}</p></article>`).join(''):projectContext()?'':`<div class="chat-empty"><h3>从问题开始</h3><p>告诉我希望改善什么、已有多少数据，或这一轮可以安排多少实验。</p><button class="suggestion" data-say="载入CsPbBr3发光配体筛选示例，帮我推荐3个候选">载入纳米晶案例，推荐3个候选</button><button class="suggestion" data-say="请帮我检索提高CsPbBr3纳米晶耐湿稳定性的研究，并整理实验行动卡">查找纳米晶稳定性的研究思路</button></div>`}</div><form class="chat-form" id="chat-form">${autoDemo?`<div class="demo-phase">${esc(autoDemo.phase||"准备开始")}</div>`:""}<textarea id="chat-input" aria-label="向 Amadeus 提问" placeholder="继续提问，或说：第二个买不到，换一个…" ${running()?'disabled':''}>${esc(chatDraft)}</textarea><div class="btn-row"><small>对话会同步更新工作区</small><button class="btn primary small" ${running()?'disabled':''}>发送 ${icon('send')}</button></div></form></section>`;}
function status(){const o=p.operation;if(o.status==='running')return `<div class="status" role="status"><span><i class="spinner"></i>${esc(o.message)}</span><button class="btn small" data-do="cancel">停止</button><div class="activity-track" role="progressbar" aria-label="正在处理"><i></i></div></div>`;if(['failed','interrupted'].includes(o.status))return `<div class="status error" role="alert"><span>${esc(o.message)}</span><button class="btn small" data-do="dismiss-error">知道了</button></div>`;return '';}
function chart(c){if(!c?.curve)return '';const lines=[c.curve,...(c.measured_curve?[c.measured_curve]:[])];const vals=lines.flat();const low=Math.min(0,...vals),high=Math.max(...vals)*1.08||1, dose=c.dose;const width=520,height=200;const pts=v=>v.map((y,i)=>`${45+450*(dose[i]-dose[0])/(dose.at(-1)-dose[0]||1)},${160-125*(y-low)/(high-low)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="配体用量与相对发光曲线"><path d="M45 25V160H495" fill="none" stroke="#c4c8d0"/>${[0,.5,1].map(t=>`<text x="38" y="${164-t*125}" text-anchor="end">${num(low+t*(high-low))}</text><path d="M45 ${160-t*125}H495" stroke="#e8eaee"/>`).join('')}<polyline points="${pts(c.curve)}" fill="none" stroke="#245dcc" stroke-width="2.5"/>${c.measured_curve?`<polyline points="${pts(c.measured_curve)}" fill="none" stroke="#99582a" stroke-width="2.5"/>`:''}<text x="45" y="179">${Number(dose[0]).toFixed(1)}</text><text x="495" y="179" text-anchor="end">${Number(dose.at(-1)).toFixed(1)}</text><text x="270" y="196" text-anchor="middle">加入量 / nmol</text><text x="45" y="15">相对发光 FOM</text></svg><div class="legend"><span>预测曲线</span>${c.measured_curve?'<span class="measured">历史实测</span>':''}</div>`;}
function task(){return `<section class="sheet"><div class="task-line"><h2>当前研究目标</h2><span class="pill">第 ${p.round} 轮</span></div><p class="task-goal">${esc(p.task.goal||'在左侧描述目标，或载入一个研究案例。')}</p><div class="task-meta"><span>测试名额<strong>${p.task.budget}</strong></span><span>已记录<strong>${p.measurements.filter(m=>m.status==='completed').length}</strong></span>${p.analysis?`<span>候选<strong>${p.analysis.candidates.length}</strong></span>`:''}</div><details><summary>调整目标与名额</summary><form id="task-form"><label class="field"><span>研究目标</span><textarea id="task-goal">${esc(p.task.goal)}</textarea></label><div class="btn-row" style="margin-top:12px"><label class="field">测试名额<input id="task-budget" aria-label="测试名额" type="number" min="1" value="${p.task.budget}" style="width:100px"></label><button class="btn small" ${running()?'disabled':''}>应用修改</button></div></form></details></section>`;}
function recommendations(){const a=p.analysis,map=known();if(!a)return `<section class="sheet empty"><h3>把目标变成下一步行动</h3><p>载入公开案例、上传实验数据，或在左侧提出研究问题。</p><div class="btn-row"><button class="btn primary" data-do="example-here" ${running()?'disabled':''}>分析纳米晶案例</button><button class="btn" data-view="data">添加数据</button></div></section>`;const chosen=p.selected.map(i=>map[i]).filter(Boolean);const detail=map[selectedDetail]||chosen[0];return `<section class="sheet"><div class="section-title"><h2>${chosen.length?'优先测试这'+chosen.length+'个候选':'本轮候选已完成'}</h2><button class="btn small" data-view="plan">编辑实验计划 ${icon('arrow')}</button></div><div class="candidate-list">${chosen.map((c,i)=>`<article class="candidate"><span class="position">${i+1}</span>${c.svg?`<div class="structure">${c.svg}</div>`:'<div class="structure"><span class="prediction">'+num(c.prediction)+'</span></div>'}<div><h3>${esc(candidateName(c))}</h3><small>${esc(c.features?.formula?c.id+(c.features.temperature_kind?' · '+(c.features.temperature_k?c.features.temperature_k+' K':c.features.temperature_kind):''):c.formula||predictionLabel(a))}${c.rank!=null?' · 融合名次 '+c.rank:''}</small></div><div class="candidate-actions"><button class="btn small quiet" data-detail="${esc(c.id)}">查看</button><button class="btn small" data-exclude="${esc(c.id)}" ${running()?'disabled':''}>换一个</button></div></article>`).join('')}</div>${detail?`<div class="candidate-detail"><div><h3>${esc(candidateName(detail))}</h3>${chart(detail)||'<p class="step-note">预测 '+esc(predictionLabel(a))+'：'+num(detail.prediction)+' '+esc(a.unit||'')+'</p>'}</div><div class="rank-detail">${detail.rank!=null?`融合名次值<strong>${detail.rank}</strong>曲线排名 ${detail.paired_rank}<br>评分排名 ${detail.direct_rank}<p class="step-note">两路名次等权合并，数值越小越优先。</p>`:`当前模型<strong style="font-size:18px">${esc(a.model)}</strong><p>目标：${esc(a.metric)}</p>`}</div></div>`:''}<details><summary>查看全部候选与分析详情</summary>${allCandidates()}<p>${esc(a.model)} · ${a.training_count} 条历史${a.kind==='specialist'?'配体':'记录'}${a.seconds?' · 原分析耗时 '+a.seconds+' 秒':''}</p>${a.kind==='specialist'?'<p>Q为40个用量点中最高4点的平均相对发光表现。来源：Kim et al., ACS Nano 2024。</p>':''}${a.scores?scoreTable(a):''}</details></section>`;}
function allCandidates(){const a=p.analysis,map=known(),completed=done();return `<div class="table-wrap"><table><thead><tr><th>候选</th><th>预测 ${esc(predictionLabel(a))}</th><th>状态</th><th>操作</th></tr></thead><tbody>${a.order.map(id=>{const c=map[id],excluded=p.excluded.includes(id);return `<tr><td>${esc(candidateName(c))}</td><td>${num(c.prediction)}</td><td>${completed.has(id)?'已完成':excluded?'已排除':p.selected.includes(id)?'本轮推荐':'备选'}</td><td>${!completed.has(id)?`<button class="btn small" ${running()?'disabled':''} ${excluded?'data-restore':'data-exclude'}="${esc(id)}">${excluded?'恢复':'排除'}</button>`:''}</td></tr>`;}).join('')}</tbody></table></div>`;}
function scoreTable(a){return `<p class="step-note">${esc(a.validation)}</p><div class="table-wrap"><table><thead><tr><th>模型</th><th>${esc(a.score_label)}</th></tr></thead><tbody>${a.scores.map(s=>`<tr><td>${esc(s.model)}${s.model===a.model?' · 已采用':''}</td><td>${num(s.score)}</td></tr>`).join('')}</tbody></table></div>`;}
function actions(){if(!p.actions.length)return '';return `<section class="sheet"><div class="section-title"><h2>建议开展的实验</h2><button class="btn small" data-view="plan">加入实验计划</button></div>${p.actions.map(a=>`<article class="action-card"><h3><input type="checkbox" data-action-id="${a.id}" aria-label="选择 ${esc(a.title)}" ${a.selected?'checked':''} ${running()?'disabled':''}>${esc(a.title)}</h3><p>${rich(a.reason)}</p><p>条件：${esc(a.condition||'在计划中补充')}<br>观察指标：${esc(a.metric||'在计划中补充')}</p>${a.sources.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noreferrer">来源 ${i+1}</a>`).join('')}</article>`).join('')}</section>`;}
function sources(){return p.sources.length?`<section class="sheet"><h2>研究资料</h2>${p.sources.map(s=>`<article class="source"><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.title)}</a><p>${esc(s.summary)}</p></article>`).join('')}</section>`:'';}
function featureComparison(a){const groups={};for(const r of a.scores||[])if(r.recipe&&!r.optimized&&r.estimator!=='Dummy'){if(!groups[r.recipe]||r.score<groups[r.recipe].score)groups[r.recipe]=r;}const max=Math.max(1,...Object.values(groups).map(r=>r.score));return `<div class="result-bars">${Object.values(groups).map(r=>`<div><span>${esc(({composition:'组成特征',condition:'实验条件',element_fraction:'元素比例',chemistry_descriptor:'材料描述符',combined:'组合特征'})[r.recipe]||r.recipe)}</span><div class="bar-track"><i style="width:${r.score/max*100}%"></i></div><strong>${num(r.score)}</strong></div>`).join('')}</div><p class="step-note">各特征组内最佳默认模型 · 分组验证MAE，越低越好。${a.replay?'本机真实运行快照。':''}</p>`;}
function engineView(){const drafts=p.extraction_drafts||[],versions=p.dataset_versions||[],cfg=p.mapping||{};return `<div class="page-intro"><h1>资料与模型引擎</h1><p>将资料整理成实验表，比较特征和模型，生成本轮候选。</p></div><section class="sheet"><h2>${esc(researchCases[p.research_context?.example]?.title||'选择一个公开研究')}</h2>${p.research_context?.example?`<p>${esc(researchCases[p.research_context.example]?.description||p.task.goal)} · ${esc(referenceLabel())}</p><p class="step-note">${esc(researchCases[p.research_context.example]?.detail||'')}。当前推荐采用已完成的分析结果，可继续安排计划与核对结果。</p>`:''}<div class="case-picker"><label class="field">公开研究<select id="research-example">${Object.entries(researchCases).map(([id,c])=>`<option value="${id}" ${p.research_context?.example===id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><button class="btn" data-do="choose-material" ${running()?'disabled':''}>选择这个研究</button></div></section><section class="sheet"><h2>从资料提取实验记录</h2><form id="extract-form"><label class="field">资料标题<input id="extract-name" value="实验资料"></label><label class="field">正文或实验表说明<textarea id="extract-text" placeholder="粘贴论文中的实验记录，保留样品、条件、性能和单位。"></textarea></label><label class="field">或导入PDF<input type="file" id="extract-pdf" accept=".pdf"></label><button class="btn primary" ${running()?'disabled':''}>提取并核对原文</button></form></section>${drafts.map(d=>`<section class="sheet"><h2>${esc(d.filename)} · 提取草稿</h2><p>${d.records.length} 条记录；${d.issues.length} 项字段未匹配原文证据。</p><details><summary>查看原文依据与单位</summary><pre>${esc(JSON.stringify(d.records,null,2))}</pre></details><form class="accept-form" data-draft-id="${d.id}"><label class="field">修订记录（values、evidence、units）<textarea name="records" style="min-height:170px">${esc(JSON.stringify(d.records,null,2))}</textarea></label><label class="field">接受为<select name="kind"><option value="training">历史实验表</option><option value="candidates">候选表</option></select></label><button class="btn primary">接受为可用数据</button></form></section>`).join('')}<section class="sheet"><h2>数据版本与字段检查</h2>${versions.length?versions.map(v=>`<details><summary>${esc(v.reason)} · ${v.audit.rows} 条 · ${esc(v.kind)} · ${esc(v.id)}</summary><pre>${esc(JSON.stringify(v.audit,null,2))}</pre></details>`).join(''):'<p>导入数据后显示缺失、重复及条件变化范围。</p>'}<form id="process-form"><label class="field">处理对象<select id="process-kind"><option value="training">历史实验表</option><option value="candidates">候选表</option></select></label><label class="field">转换规则（JSON）<textarea id="process-rules" placeholder='[{"column":"volume_ul","output":"amount_nmol","operation":"amount_nmol","concentration_column":"stock_um"}]'>[]</textarea></label><label class="field">结构列（可选，SMILES或InChI）<input id="process-structure" placeholder="例如 smiles"></label><button class="btn">执行整理并保存版本</button></form><details><summary>查看处理历史</summary><pre>${esc(JSON.stringify(p.processing_history||[],null,2))}</pre></details></section><section class="sheet"><h2>特征、模型与搜索配置</h2><p>配置目标、分组及特征组；真实比较 RF、ET、XGBoost、LightGBM、Ridge和简单参照。optimize启用训练内部Top-K与贝叶斯搜索。</p><form id="engine-train-form"><div class="mapping-grid"><label class="field">优化设置<label><input id="engine-optimize" type="checkbox" ${cfg.optimize?'checked':''}>比较Top-K与贝叶斯搜索</label></label><label class="field">每个模型的搜索次数<input id="engine-trials" type="number" min="1" value="${cfg.search_trials||4}"></label><label class="field">主要选择依据<select id="engine-metric"><option value="mae" ${cfg.selection_metric!=='regret'?'selected':''}>预测误差 MAE</option><option value="regret" ${cfg.selection_metric==='regret'?'selected':''}>有限名额的筛选差距</option></select></label></div><details><summary>调整目标、字段与特征组</summary><label class="field">任务配置（JSON）<textarea id="engine-config" style="min-height:300px">${esc(JSON.stringify(cfg,null,2))}</textarea></label></details><button class="btn primary" ${running()?'disabled':''}>${window.AmadeusDemo?'读取真实运行对照':'运行特征与模型比较'}</button></form>${p.analysis?.kind==='tabular'?`<h3>本次运行</h3>${featureComparison(p.analysis)}${scoreTable(p.analysis)}<p>采用：${esc(p.analysis.model)} · ${esc(p.analysis.validation)} · ${p.analysis.seconds||'—'} 秒</p><details><summary>所选特征与优化记录</summary><pre>${esc(JSON.stringify({selected_features:p.analysis.selected_features,search:p.analysis.search,evaluation:p.analysis.evaluation_note},null,2))}</pre></details>`:''}</section>`;}
function dataView(){const ds=p.datasets,cols=ds.training?.columns||[],m=p.mapping||{};const options=(list,val,empty=false)=>(empty?'<option value="">不分组</option>':'')+list.map(c=>`<option value="${esc(c)}" ${c===val?'selected':''}>${esc(c)}</option>`).join('');return `<div class="page-intro"><h1>数据与候选</h1><p>导入历史结果和待测候选，选择需要预测的指标。</p></div><section class="sheet"><div class="section-title"><h2>实验数据</h2><button class="btn small" data-do="sample-csv" ${running()?'disabled':''}>载入配方示例</button></div><p class="muted">示例使用公开纳米晶配方与发射峰数据。</p>${['training','candidates'].map(k=>`<div class="upload-area"><h3>${k==='training'?'历史实验表':'待测候选表'}${ds[k]?`<span class="pill">${ds[k].count} 条记录</span>`:''}</h3><input type="file" accept=".csv,.json,text/csv,application/json" data-upload="${k}" aria-label="上传${k==='training'?'历史实验表':'待测候选表'}" ${running()?'disabled':''}>${ds[k]?`<div class="file-list">${esc(ds[k].filename)}</div><div class="table-wrap"><table><thead><tr>${ds[k].columns.map(c=>'<th>'+esc(c)+'</th>').join('')}</tr></thead><tbody>${ds[k].preview.map(r=>'<tr>'+ds[k].columns.map(c=>'<td>'+esc(r[c])+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`:`<small>${k==='training'?'包含实验条件与已测指标。':'包含候选编号与相同的输入特征。'}</small>`}</div>`).join('')}<div class="btn-row"><a href="./sample-history.csv" download>下载历史表样例</a><a href="./sample-candidates.csv" download>下载候选表样例</a></div></section>${cols.length?`<section class="sheet"><h2>这次要预测什么？</h2><form id="train-form"><div class="mapping-grid" style="margin-top:18px"><label class="field"><span>目标列</span><select id="map-target">${options(cols,m.target)}</select></label><label class="field"><span>候选编号列</span><select id="map-id">${options(ds.candidates?.columns||cols,m.id)}</select></label><label class="field"><span>任务</span><select id="map-task"><option value="regression" ${m.task==='regression'?'selected':''}>预测数值</option><option value="classification" ${m.task==='classification'?'selected':''}>二分类 / 是否达标</option></select></label><label class="field"><span>优化方向</span><select id="map-direction"><option value="max" ${m.direction==='max'?'selected':''}>越高越好</option><option value="min" ${m.direction==='min'?'selected':''}>越低越好</option></select></label><label class="field"><span>分组列</span><select id="map-group">${options(cols,m.group,true)}</select></label><label class="field"><span>指标单位</span><input id="map-unit" value="${esc(m.unit||'')}" placeholder="例如 nm、MPa"></label><label class="field"><span>二分类目标类别</span><input id="map-positive" value="${esc(m.positive||'')}" placeholder="回归任务可留空"></label></div><p class="step-note">输入特征</p><div class="check-list">${cols.map(c=>`<label><input type="checkbox" name="feature" value="${esc(c)}" ${(m.features||[]).includes(c)?'checked':''}>${esc(c)}</label>`).join('')}</div><button class="btn primary" ${running()||!ds.candidates?'disabled':''}>比较模型并生成建议</button><p class="step-note">自动比较 ET、线性模型与梯度提升树。结果会进入同一份实验计划。</p></form></section>`:''}${p.analysis?recommendations():''}`;}
function guidedCase(){return ['double_perovskites_gap','citrine_thermal_conductivity'].includes(p?.research_context?.example);}
function suggestedCondition(c){if(!guidedCase())return '';const f=c?.features||{};if(p.research_context.example==='double_perovskites_gap')return ['GLLB-SC 计算参考',...['a_1','b_1','a_2','b_2'].filter(k=>f[k]).map(k=>k+'='+f[k])].join('；');return f.temperature_k?`测试温度 ${f.temperature_k} K`:f.temperature_kind==='room temperature'?'室温（原数据未注明具体温度）':f.temperature_kind==='standard'?'standard（沿用原数据条件标记）':'沿用原数据记录条件';}
function guidedNote(){return guidedCase()?'按公开'+referenceLabel()+'核对候选预测；保留原数据条件。':'';}
function researchGuide(){if(!guidedCase()||!p.analysis)return '';let title,text,button;
 if(view==='report'){title='研究流程已完成';text='报告已汇总模型比较、候选预测和已记录结果。点击下方“打开完整报告 / 保存 PDF”即可保存。';button='';}
 else if(p.round>1){title='最后一步 · 查看研究报告';text='下一轮已跳过记录过的候选。现在可以汇总本轮研究并保存报告。';button='<button class="btn primary" data-view="report">查看研究报告</button>';}
 else if(p.measurements.some(m=>m.round===p.round&&m.analysis_id===p.analysis.id)){title='第 4 步 · 安排下一轮';text='参考结果已填入记录。继续查看模型会优先推荐哪些尚未记录的候选。';button='<button class="btn primary" data-do="next-round">安排下一轮</button>';}
 else if(plan()){title='第 3 步 · 核对公开结果';text='计划已保存。点击后会把所选候选的'+referenceLabel()+'填入结果表，无需手动抄写。';button='<button class="btn primary" data-do="history-results">填写并查看'+esc(referenceLabel())+'</button>';}
 else if(view==='plan'){title='第 2 步 · 保存本轮计划';text='候选、指标、单位、已知条件和备注已填好。可以修改，确认后点击保存。';button='<button class="btn primary" data-do="guide-save-plan">确认并保存计划</button>';}
 else{title='第 1 步 · 查看候选并安排计划';text='已有分析结果已准备好。先看优先候选，再进入自动填好的计划表。';button='<button class="btn primary" data-view="plan">查看已填写的计划</button>';}
 return `<section class="research-guide" aria-label="研究流程指引"><div><h2>${title}</h2><p>${text}</p></div>${running()||busy?'<span role="status">正在更新…</span>':button}</section>`;
}
function draftItems(){const current=plan(),map=known(),prior=Object.fromEntries((current?.items||[]).map(i=>[i.candidate_id,i]));return p.analysis?p.selected.map(id=>prior[id]||({candidate_id:id,name:candidateName(map[id]),condition:suggestedCondition(map[id]),metric:p.task.metric,unit:p.task.unit||'',note:guidedNote()})):p.actions.filter(a=>a.selected).map(a=>prior[a.id]||({candidate_id:a.id,name:a.title,condition:a.condition,metric:a.metric,unit:'',note:a.reason}));}
function planView(){const items=draftItems();return `<div class="page-intro"><h1>安排本轮实验</h1><p>把建议调整为实际要测试的名单，补充条件后保存。</p></div><section class="sheet"><div class="section-title"><h2>第 ${p.round} 轮计划</h2>${plan()?'<span class="pill">版本 '+plan().version+(JSON.stringify(items.map(i=>i.candidate_id))===JSON.stringify(plan().items.map(i=>i.candidate_id))?' · 已保存':' · 名单已调整')+'</span>':'<span class="pill">草稿</span>'}</div>${items.length?`<form id="plan-form"><div class="table-wrap"><table><thead><tr><th>候选 / 行动</th><th>测试条件</th><th>指标</th><th>单位</th><th>备注</th></tr></thead><tbody>${items.map(i=>`<tr data-plan-id="${esc(i.candidate_id)}" data-name="${esc(i.name)}"><td class="wrap">${esc(i.name)}</td><td><input data-field="condition" aria-label="${esc(i.name)}测试条件" value="${esc(i.condition)}" placeholder="填写条件或用量"></td><td><input data-field="metric" aria-label="${esc(i.name)}指标" value="${esc(i.metric)}"></td><td><input data-field="unit" aria-label="${esc(i.name)}单位" value="${esc(i.unit)}"></td><td><input data-field="note" aria-label="${esc(i.name)}备注" value="${esc(i.note)}"></td></tr>`).join('')}</tbody></table></div><label class="field" style="margin:18px 0"><span>本轮备注</span><textarea id="plan-notes" placeholder="例如：统一使用同一批纳米晶，记录测试条件。">${esc(plan()?.notes??guidedNote())}</textarea></label><div class="btn-row"><button class="btn primary" ${running()?'disabled':''}>保存本轮计划</button>${plan()?`<a class="btn" href="/api/projects/${p.id}/csv" download>导出已保存实验表</a><button class="btn" type="button" data-view="results">记录实验结果</button>`:''}</div></form>`:'<div class="empty"><p>先在工作区生成候选建议或实验行动卡，再安排本轮计划。</p><div class="btn-row"><button class="btn" data-view="overview">返回研究工作区</button></div></div>'}</section>${p.plans.length?`<section class="sheet"><h2>已保存的计划</h2>${p.plans.slice().reverse().map(q=>`<div class="saved-row"><span>第 ${q.round} 轮 · 版本 ${q.version} · ${q.items.length} 项实验</span><small>${date(q.created)}</small></div>`).join('')}</section>`:''}`;}
const recordedValue=id=>p.measurements.filter(m=>m.candidate_id===id&&m.round===p.round).at(-1);
function resultsView(){const q=plan();const a=p.analysis;return `<div class="page-intro"><h1>记录实验结果</h1><p>记录这轮发生了什么，继续安排下一轮。</p></div>${q?`<section class="sheet"><div class="section-title"><h2>第 ${p.round} 轮</h2>${a?.kind==='specialist'||researchCases[p.research_context?.example]?`<button class="btn small" data-do="history-results" ${running()?'disabled':''}>查看${esc(referenceLabel())}</button>`:''}</div><form id="results-form"><div class="table-wrap"><table><thead><tr><th>候选 / 行动</th><th>结果值</th><th>单位</th><th>状态</th><th>说明</th></tr></thead><tbody>${q.items.map(i=>`<tr data-result-id="${esc(i.candidate_id)}" data-condition="${esc(i.condition)}"><td class="wrap">${esc(i.name)}</td><td><input data-field="value" aria-label="${esc(i.name)}测量值" type="number" step="any" value="${esc(recordedValue(i.candidate_id)?.value??'')}" placeholder="输入结果值"></td><td><input data-field="unit" aria-label="${esc(i.name)}结果单位" value="${esc(i.unit)}"></td><td><select data-field="status" aria-label="${esc(i.name)}状态"><option value="completed">完成</option><option value="failed">失败</option><option value="pending">待测</option></select></td><td><input data-field="note" aria-label="${esc(i.name)}结果说明" value="${esc(recordedValue(i.candidate_id)?.note||'')}" placeholder="实验现象或失败原因"></td></tr>`).join('')}</tbody></table></div><div class="btn-row" style="margin-top:18px"><button class="btn primary" ${running()?'disabled':''}>保存填写的结果</button><label class="btn">导入结果 CSV<input type="file" accept=".csv" data-upload="results" hidden ${running()?'disabled':''}></label></div></form><p class="step-note">只保存已填写的行；重复测量保留为新记录。${a?.task==='classification'?'二分类填 1 表示目标类别，0 表示另一类别；也可在说明中填原始类别名称。':''}</p></section>`:'<section class="sheet empty"><h3>先安排本轮实验</h3><p>保存计划后，即可录入测量或导入结果。</p><div class="btn-row"><button class="btn" data-view="plan">查看实验计划</button></div></section>'}${p.measurements.length?`<section class="sheet"><div class="section-title"><h2>研究进展</h2><span class="pill">${p.measurements.filter(m=>m.status==='completed').length} 项已记录</span></div><div class="table-wrap"><table><thead><tr><th>轮次</th><th>候选</th><th>结果</th><th>状态</th><th>来源</th></tr></thead><tbody>${p.measurements.slice().reverse().map(m=>`<tr><td>${m.round}</td><td>${esc(m.candidate_id)}</td><td class="wrap">${m.value!=null?num(m.value)+' '+esc(m.unit):esc(m.note)}</td><td>${({completed:'完成',failed:'失败',pending:'待测'})[m.status]}</td><td>${esc(m.source)}</td></tr>`).join('')}</tbody></table></div><div class="btn-row" style="margin-top:20px"><button class="btn primary" data-do="next-round" ${running()||!p.measurements.some(m=>m.round===p.round)?'disabled':''}>安排下一轮 ${icon('arrow')}</button>${a?.kind==='tabular'&&!window.AmadeusDemo?`<button class="btn" data-do="retrain" ${running()?'disabled':''}>使用新结果更新分析</button>`:''}<button class="btn" data-view="report">生成研究报告</button></div></section>`:''}${a?.evidence?`<section class="sheet"><h2>原案例同预算对照</h2><p class="step-note">固定案例原始名单 · 推荐 ${a.legacy_job.budget} 个；当前用户计划见上方记录。</p><div class="table-wrap"><table><thead><tr><th>方法</th><th>原始名单最佳实测 Q</th></tr></thead><tbody>${[['paired_ET','成对 ET'],['direct_Q_ET','直接评分 ET'],['equal_rank','等权融合'],['paired_RF','成对 RF']].map(([k,l])=>`<tr><td>${l}</td><td>${num(a.evidence.metrics[k].selected_best)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;}
const recordExamples=[{"id": "2022_0519_SL01_0008_0015_robotinput@@A01", "tag": 1, "volume": 10, "concentration": 100.0, "fom": 0.9010187175899949, "conditions": [{"name": "Temperature (C):", "value": 25.0}, {"name": "Stir Rate (rpm):", "value": 750.0}, {"name": "Mixing time1 (s):", "value": 600.0}, {"name": "Mixing time2 (s):", "value": 600.0}, {"name": "Reaction time (s):", "value": 60.0}]}, {"id": "2022_0519_SL01_0008_0015_robotinput@@A06", "tag": 3, "volume": null, "concentration": null, "fom": 0.9819194365191104, "conditions": [{"name": "Temperature (C):", "value": 25.0}, {"name": "Stir Rate (rpm):", "value": 750.0}, {"name": "Mixing time1 (s):", "value": 600.0}, {"name": "Mixing time2 (s):", "value": 600.0}, {"name": "Reaction time (s):", "value": 60.0}]}, {"id": "2022_0519_SL01_0008_0015_robotinput@@B06", "tag": 2, "volume": null, "concentration": null, "fom": null, "conditions": [{"name": "Temperature (C):", "value": 25.0}, {"name": "Stir Rate (rpm):", "value": 750.0}, {"name": "Mixing time1 (s):", "value": 600.0}, {"name": "Mixing time2 (s):", "value": 600.0}, {"name": "Reaction time (s):", "value": 60.0}]}, {"id": "2022_0520_SL05_0018_0014_robotinput@@A02", "tag": 1, "volume": 272, "concentration": 100.0, "fom": null, "conditions": []}];
const openingQuestion='我想提高钙钛矿纳米晶的发光效率，手里有一些论文和历史实验数据。不同文章的条件不一样，帮我理清能比较什么，再安排下一轮实验。';
function projectContext(){try{return JSON.parse(localStorage.getItem('amadeus-context-'+p.id)||'null');}catch{return null;}}
function decisionCard(){return `<section class="sheet"><h2>把问题变成可执行的任务</h2><div class="decision-grid"><div><small>研究目标</small><h3>提高纳米晶发光表现</h3><p>从配体和加入量寻找下一轮候选。</p></div><div><small>本轮可用证据</small><h3>公开实验曲线</h3><p>结构、用量与实测响应能够对应。</p></div></div><div class="metric-choice"><div><strong>本轮采用 · 相对发光 Q</strong><p>比较同一数据体系中配体的表现，直接连接现有筛选模型。</p></div><div><strong>另立任务 · 绝对 PLQY</strong><p>需要吸收、参比等配套信息；文献报告值可单独整理。</p></div></div><p class="step-note">PL反映测到的发光信号；PLQY反映吸收光子转化为发射光子的比例。</p></section>`;}
function recordProcessing(){const n=autoDemo?.evidenceCount??6;return `<section class="sheet"><h2>把原始记录整理成实验数据</h2><p>按记录身份分流，再统一加入量、检查响应，最后按配体组成曲线。</p><div class="table-wrap"><table><thead><tr><th>原始记录 / 点击追溯</th><th>读取字段</th><th>整理结果</th></tr></thead><tbody>${recordExamples.slice(0,Math.min(4,n)).map((x,i)=>`<tr class="evidence-row"><td><details><summary>${esc(x.id.split('@@').at(-1))} · ${i===3?'异常样品':x.tag===1?'实验样品':x.tag===3?'参照':'空白'}</summary><p>${esc(x.id)}</p><pre>${esc(JSON.stringify(x,null,2))}</pre></details></td><td>${x.volume!=null?`${num(x.concentration)} μM × ${x.volume} μL`:'WallTag = '+x.tag}<br>FOM：${num(x.fom)}</td><td>${i===3?'响应缺失 → 标记无效测量':x.tag===1?`${num(x.concentration*x.volume/1000)} nmol → 保留样品`:x.tag===3?'参照 → 单独保留':'空白 → 移出候选筛选'}</td></tr>`).join('')}</tbody></table></div>${n>=5?'<div class="processing-outcome"><strong>配体曲线已经对齐</strong><p>93种配体 → 90种完整有效曲线用于现有评估。每种40点；用量统一为nmol；Q取最高4点的平均响应。</p><p>示例记录背景：间二甲苯；温度25°C；搅拌750 rpm；两段混合各600 s；反应时间60 s。分段时间分别保留，避免混为同一处理时长。纯化次数待补充。</p></div>':''}</section>`;}
function modelReasoning(){const a=p.analysis;if(a?.kind!=='specialist')return '';const available=a.candidates.filter(c=>!p.excluded.includes(c.id)&&!done().has(c.id));const lists=[['曲线分支','paired_rank'],['直接评分分支','direct_rank'],['等权融合','rank']];return `<section class="sheet"><h2>为什么优先测这些候选？</h2><p>曲线分支比较用量响应，评分分支预测整体表现；两路名次等权合并。</p><div class="model-columns">${lists.map(([label,key])=>`<div><h3>${label}</h3><ol>${available.slice().sort((x,y)=>x[key]-y[key]||a.order.indexOf(x.id)-a.order.indexOf(y.id)).slice(0,p.task.budget).map(c=>`<li><strong>${esc(candidateName(c))}</strong><small>名次值 ${c[key]}</small></li>`).join('')}</ol></div>`).join('')}</div>${p.excluded.length?`<p class="decision-change">已排除 ${p.excluded.map(esc).join('、')}，按融合排序补位；本轮计划使用当前 ${p.task.budget} 个候选。</p>`:''}<p class="step-note">名次值含并列处理；当前窗口展示本轮可用候选。</p></section>`;}
function researchReview(){const a=p.analysis;if(a?.kind!=='specialist'||!p.measurements.length)return '';const map=known(),ms=p.measurements.filter(m=>m.analysis_id===a.id&&m.value!=null);if(!ms.length)return '';const best=ms.reduce((x,y)=>x.value>y.value?x:y);return `<section class="sheet"><h2>本轮结果怎样影响下一步？</h2><p><strong>${esc(map[best.candidate_id]?.name||best.candidate_id)}</strong> 在当前已记录候选中表现最好，实测 Q 为 ${num(best.value)}。</p><div class="table-wrap"><table><thead><tr><th>候选</th><th>曲线分支</th><th>直接评分</th><th>实测 Q</th></tr></thead><tbody>${ms.map(m=>`<tr><td>${esc(map[m.candidate_id]?.name||m.candidate_id)}</td><td>${num(map[m.candidate_id]?.prediction)}</td><td>${num(map[m.candidate_id]?.direct)}</td><td>${num(m.value)}</td></tr>`).join('')}</tbody></table></div><p>下一轮从剩余候选中继续选择，跳过已完成项和已排除项。研究记录保留预测、实测和人工调整的对应关系。</p></section>`;}
function decisionSummary(){if(!projectContext())return '';return `<section class="sheet"><h2>研究决策记录</h2><ol class="decision-log"><li>从发光效率问题出发，先区分相对发光与绝对PLQY。</li><li>整理公开记录，选择结构、用量与响应可对应的CsPbBr₃任务。</li><li>比较两路模型，按融合名次安排 ${p.task.budget} 个测试名额。</li><li>${p.excluded.length?'排除 '+p.excluded.map(esc).join('、')+'，替代候选补位。':'按当前可用候选生成计划。'}</li><li>已记录 ${p.measurements.length} 条结果，当前推进到第 ${p.round} 轮。</li></ol></section>`;}
const evidenceFields=[
 ['材料体系','CsPbBr₃ 纳米晶','论文研究对象','限定本次筛选范围'],
 ['候选配体','93种；90种完整有效曲线','作者公开数据核查','90种用于现有评估'],
 ['用量','每条完整曲线40个测量点','ligand_solutions.volume / concentration','统一展示为 nmol'],
 ['响应指标','相对发光 FOM；曲线汇总为 Q','properties.FigureOfMerit','与绝对 PLQY 分开'],
 ['样品体积','500 μL','公开反应记录的体积核查','用于浓度与加入量换算'],
 ['溶剂与处理条件','溶剂、温度、时间、纯化次数','需逐条补充来源与语义核对','未作为当前模型输入']
];
function evidenceView(compact=false){if(p.analysis?.kind==='tabular')return compact?'':engineView();const n=autoDemo?.evidenceCount??6;if(autoDemo&&!projectContext())return '<div class="page-intro"><h1>从研究问题开始</h1><p>描述希望改善的性能、已有资料和本轮实验条件。</p></div>';return `<div class="page-intro"><h1>${compact?'数据与研究依据':'从文献到实验数据'}</h1><p>整理材料、实验条件与性能指标，为本轮筛选确定可比较的数据。</p></div>${decisionCard()}<section class="sheet"><div class="section-title"><h2>研究资料</h2><span class="pill">已整理示例资料</span></div><div class="evidence-sources"><article><small>论文 · ACS Nano 2024</small><h3>Active Learning of Ligands That Enhance Perovskite Nanocrystal Luminescence</h3><p>研究摘要：比较配体与用量对钙钛矿纳米晶发光表现的影响。</p><a href="https://doi.org/10.1021/acsnano.4c02094" target="_blank" rel="noreferrer">查看论文 ↗</a></article><article><small>作者公开数据 · 固定版本</small><h3>配体—用量—实测响应</h3><p>4,447条反应记录，包含实验样品、参照与空白。先区分记录类型，再整理配体曲线。</p><a href="https://github.com/qai222/ALLiS/tree/1796d18496c669d554fa165a88d83e7b3cd9a905" target="_blank" rel="noreferrer">查看数据来源 ↗</a></article></div><p class="step-note">下方为已核查信息的整理回放；摘要不是原文引句。</p></section>${recordProcessing()}<section class="sheet"><div class="section-title"><h2>实验信息整理</h2><span class="pill">${n} / 6 类字段</span></div><div class="table-wrap"><table><thead><tr><th>字段</th><th>提取与整理</th><th>追溯与用途</th></tr></thead><tbody>${evidenceFields.slice(0,n).map((r,i)=>`<tr class="evidence-row"><td>${r[0]}</td><td>${r[1]}</td><td><details><summary>查看依据</summary><p>${r[2]}</p><p>${r[3]}</p></details></td></tr>`).join('')}</tbody></table></div>${n<6?'<p role="status">正在展开已整理字段…</p>':''}</section>${n===6?`<section class="sheet"><h2>确定本轮筛选条件</h2><p>先使用条件可对齐的 CsPbBr₃ 配体数据，以相对发光 Q 为目标。PLQY作为独立指标保留，不混入本次评分。</p><div class="check-list"><span class="pill">CsPbBr₃</span><span class="pill">结构 + 用量</span><span class="pill">Q 越高越好</span><span class="pill">18种演示候选</span></div><p>Q：每条曲线最高4个测量点的平均相对发光表现。接下来通过两路模型生成本轮优先名单。</p>${!compact?'<button class="btn primary" data-view="overview">进入候选筛选 →</button>':''}</section>`:''}`;}
function reportVisuals(){
 const a=p.analysis;if(!a)return '';
 if(a.kind==='tabular'){const map=known(),records=p.measurements.filter(m=>m.analysis_id===a.id&&m.value!=null);return `<section class="sheet"><h2>模型与特征比较</h2>${featureComparison(a)}${scoreTable(a)}</section><section class="sheet"><h2>候选预测与${esc(referenceLabel())}</h2><div class="table-wrap"><table><thead><tr><th>候选</th><th>预测 ${esc(a.metric)}</th><th>已记录${esc(referenceLabel())}</th><th>单位</th></tr></thead><tbody>${(records.length?records:p.selected.map(id=>({candidate_id:id,value:null}))).map(m=>`<tr><td>${esc(candidateName(map[m.candidate_id])||m.candidate_id)}</td><td>${num(map[m.candidate_id]?.prediction)}</td><td>${num(m.value)}</td><td>${esc(a.unit)}</td></tr>`).join('')}</tbody></table></div></section>`;}
 const map=known(),latest={};for(const m of p.measurements)if(m.value!=null&&m.analysis_id===a.id)latest[m.candidate_id]=m;
 const ids=Object.keys(latest),shown=ids.length?ids:p.selected;
 const max=Math.max(1,...ids.map(id=>latest[id].value));
 return `<section class="sheet"><h2>候选结构与响应曲线</h2><div class="report-figures">${shown.filter(id=>map[id]).slice(0,6).map(id=>{const c=map[id];return `<figure><div class="figure-title">${c.svg?'<div class="structure">'+c.svg+'</div>':''}<div><h3>${esc(candidateName(c))}</h3><small>${esc(c.formula||a.metric)}</small></div></div>${chart(c)||'<p>预测 '+num(c.prediction)+'</p>'}<figcaption>预测 ${num(c.prediction)}${latest[id]?' · 实测 '+num(latest[id].value):''}</figcaption></figure>`;}).join('')}</div></section>${ids.length?`<section class="sheet"><h2>本轮实测表现</h2><p class="step-note">当前项目的已记录结果 · ${esc(a.metric)}</p><div class="result-bars">${ids.sort((a,b)=>latest[b].value-latest[a].value).map(id=>`<div><span>${esc(map[id]?.name||id)}</span><div class="bar-track"><i style="width:${Math.max(0,latest[id].value)/max*100}%"></i></div><strong>${num(latest[id].value)}</strong></div>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>候选</th><th>曲线分支预测</th><th>直接评分预测</th><th>实测 ${esc(a.metric)}</th><th>来源</th></tr></thead><tbody>${ids.map(id=>`<tr><td>${esc(map[id]?.name||id)}</td><td>${num(map[id]?.prediction)}</td><td>${num(map[id]?.direct)}</td><td>${num(latest[id].value)}</td><td>${esc(latest[id].source)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`;
}
function reportView(){const a=p.analysis;const ready=localStorage.getItem('amadeus-report-'+p.id)!=='pending';return `<div class="page-intro"><h1>研究报告</h1><p>汇总目标、分析、实验安排和已记录的结果。</p></div><div class="btn-row" style="margin-bottom:22px"><a class="btn primary" href="/api/projects/${p.id}/report" target="_blank">打开完整报告 / 保存 PDF</a>${plan()?`<a class="btn" href="/api/projects/${p.id}/csv" download>导出已保存实验表</a>`:''}</div>${ready?`${decisionSummary()}${researchReview()}${reportVisuals()}${p.analysis?.kind==='specialist'?evidenceView(true):''}<article class="sheet report-preview"><div class="wordmark"><img class="report-logo" src="./logo.svg" alt="Amadeus" width="1968" height="382"></div><h1>${esc(p.title)}</h1><h2>研究目标</h2><p>${esc(p.task.goal)}</p><h2>分析与决策</h2><p>${a?esc(a.model)+'\n历史记录：'+a.training_count+'，候选：'+a.candidates.length: '结合检索资料与实验行动卡开展研究。'}</p>${a?.scores?scoreTable(a):''}<h2>实验进展</h2><p>已保存 ${p.plans.length} 份计划，记录 ${p.measurements.length} 条实验结果，当前第 ${p.round} 轮。</p>${p.messages.filter(m=>m.role==='assistant').slice(-1).map(m=>'<h2>最近的研究建议</h2><p>'+rich(m.content)+'</p>').join('')}<details><summary>运行与数据记录</summary><p>${a?.source?esc(a.source):'使用项目中载入的数据与资料。'}</p><a href="/api/projects/${p.id}/export" download>导出项目 JSON</a></details></article>${sources()}`:'<div class="report-pending" role="status">正在整理研究报告，完成后将在这里展示图表和正文。</div>'}`;}
function flowMeter(){
 if(!p)return '';
 const labels=['明确目标','分析候选','安排实验','记录结果','下一轮','报告'];
 const n=autoDemo?autoDemo.completed:(view==='report'?6:p.round>1?5:p.measurements.length?4:plan()?3:p.analysis||p.actions.length?2:p.task.goal?1:0);
 return `<div class="flow-meter"><div class="flow-heading"><strong>${autoDemo?'自动演示 · '+(autoDemo.phase||'准备中'):'研究进展'}</strong><span>${n} / 6 阶段</span></div><div class="flow-track" role="progressbar" aria-label="已完成阶段" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${n}"><i style="transform:scaleX(${n/6})"></i></div><div class="flow-steps">${labels.map((x,i)=>`<span class="${i<n?'passed':i===n?'current':''}">${x}</span>`).join('')}</div></div>`;
}
function render(){const scroll=$('.workspace-body')?.scrollTop||0;$('#app').innerHTML=side()+`<div class="shell"><header class="top"><div><span class="crumb">${p?'研究项目':'我的工作台'}</span><strong>${p?esc(p.title):'Amadeus'}</strong></div><div class="round"><span class="pill">${p?'第 '+p.round+' 轮':window.AmadeusDemo?'在线演示':local?'本机研究工作台':'在线案例'}</span>${autoDemo?'<span class="pill">自动演示 '+autoDemo.step+'/6</span><button class="btn small" data-do="stop-demo">停止演示</button>':''}${p?'<button class="btn small" data-view="report">导出报告</button>':''}</div></header>${p?`<main id="main" class="project-layout">${chat()}<div class="workspace-body">${flowMeter()}${researchGuide()}${status()}${view==='engine'?engineView():view==='evidence'?evidenceView():view==='overview'?task()+modelReasoning()+recommendations()+actions()+sources():view==='data'?dataView():view==='plan'?planView():view==='results'?researchReview()+resultsView():reportView()}</div></main>`:home()}</div>`;const bar=$('.flow-track i'),fraction=Number($('.flow-track')?.getAttribute('aria-valuenow')||0)/6;if(bar&&!reducedMotion()&&fraction!==lastProgress)bar.animate([{transform:`scaleX(${lastProgress})`},{transform:`scaleX(${fraction})`}],{duration:550,easing:'cubic-bezier(.16,1,.3,1)'});lastProgress=fraction;const surface=(p?.id||'home')+view;const changed=surface!==lastSurface;if($('.workspace-body'))$('.workspace-body').scrollTop=changed?0:scroll;if(!reducedMotion()&&changed){($('.workspace-body')||$('.home'))?.animate([{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,easing:'cubic-bezier(.16,1,.3,1)'});}if(!reducedMotion()&&p&&p.messages.length>lastMessageCount){$('.messages .message:last-child')?.animate([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'none'}],{duration:280,easing:'ease-out'});}const selection=(p?.selected||[]).join(',');if(!reducedMotion()&&selection!==lastSelection){document.querySelectorAll('.candidate').forEach((el,i)=>el.animate([{opacity:.3,transform:'translateY(5px)'},{opacity:1,transform:'none'}],{duration:300,delay:Math.min(i*35,175),easing:'ease-out'}));}lastSelection=selection;const operation=p?.operation;if(!reducedMotion()&&operation?.status==='complete'&&operation.id!==lastOperation){$('.workspace-body .sheet')?.animate([{boxShadow:'0 0 0 1px #91aad9'},{boxShadow:'0 0 0 1px transparent'}],{duration:650});lastOperation=operation.id;}lastSurface=surface;lastMessageCount=p?.messages.length||0;const messages=$('#messages');if(messages)messages.scrollTop=messages.scrollHeight;}
async function refreshList(){projects=await api('/api/projects');}
async function openProject(id){clearTimeout(poll);p=await api('/api/projects/'+id);view='overview';selectedDetail=null;chatDraft='';history.replaceState(null,'','#'+id);render();if(running())watch();}
async function newProject(goal='',title='新的研究项目'){if(!local){toast('请打开本机工作台创建研究项目。');return;}p=await api('/api/projects',{goal,title});view='overview';history.replaceState(null,'','#'+p.id);await refreshList();render();return p;}
async function act(action,args={},after){if(busy||running())return;busy=true;const id=p.id;try{p=await api(`/api/projects/${id}/action`,{action,args,operation_id:crypto.randomUUID()});render();await watch(after);}catch(e){toast(e.message);}finally{busy=false;render();}}
async function watch(after,origin=view){const id=p.id;for(;;){await new Promise(r=>setTimeout(r,650));if(!p||p.id!==id)return;const next=await api('/api/projects/'+id);if(JSON.stringify(next)!==JSON.stringify(p)){p=next;render();}if(!running()){await refreshList();if(p.operation.status==='failed'){toast(p.operation.message);}else if(after&&view===origin){view=after;render();}return;}}}
async function say(message){if(!message.trim())return;chatDraft='';await act('chat',{message});}
async function sample(){const hist=await fetch('./sample-history.csv').then(r=>r.text()),cand=await fetch('./sample-candidates.csv').then(r=>r.text());await act('upload',{kind:'training',text:hist,filename:'公开纳米晶配方-历史.csv'});await act('upload',{kind:'candidates',text:cand,filename:'公开纳米晶配方-候选.csv'});view='data';render();}
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function playDemo(){
 if(autoDemo||busy||running())return;
 const run={step:0,completed:0,phase:'准备研究问题',stopped:false};autoDemo=run;
 try{
  await newProject('提高 CsPbBr₃ 纳米晶的发光表现。','纳米晶发光优化 · 自动演示');
  const id=p.id;localStorage.setItem('amadeus-report-'+id,'pending');
  view='evidence';run.phase='描述研究问题';run.evidenceCount=0;render();
  const openingBox=$('#chat-input');openingBox.readOnly=true;openingBox.focus();
  for(const char of openingQuestion){if(run.stopped)return;chatDraft+=char;openingBox.value=chatDraft;await pause(/[，。？]/.test(char)?220:18+Math.random()*28);}
  await pause(600);chatDraft='';localStorage.setItem('amadeus-context-'+id,JSON.stringify({question:openingQuestion}));run.phase='梳理目标与可用数据';render();await pause(2000);
  view='evidence';run.phase='整理文献与实验数据';run.evidenceCount=0;render();
  for(let field=1;field<=6&&!run.stopped;field++){
   await pause(1300);run.evidenceCount=field;render();
   document.querySelector('.evidence-row:last-child')?.scrollIntoView({behavior:reducedMotion()?'instant':'smooth',block:'nearest'});
  }
  if(!run.stopped){await pause(2400);document.querySelector('.workspace-body .sheet:last-child')?.scrollIntoView({behavior:'smooth',block:'end'});await pause(2600);}
  if(run.stopped)return;

  const steps=[
   ['我想提高CsPbBr3纳米晶的发光表现，这一轮先测试3种配体，帮我选出优先候选。','overview'],
   ['第二个买不到，换一个，这一轮改为测试4个。','overview'],
   ['就按当前4个候选保存本轮实验计划。','plan'],
   ['载入这份计划对应的公开历史实测结果。','results'],
   ['根据已经记录的结果，安排下一轮候选。','overview'],
   ['总结本项目已完成的分析、计划和历史结果，准备研究报告。','report']
  ];
  for(let i=0;i<steps.length;i++){
   if(run.stopped||p?.id!==id)break;
   run.step=i+1;run.phase=['想一想研究目标','查看排名，调整名额','整理这一轮计划','准备查看实测结果','比较结果，继续筛选','整理研究报告'][i];view=steps[i][1];chatDraft='';render();await pause(650+Math.random()*850);if(run.stopped)break;run.phase='正在输入…';render();
   const box=$('#chat-input');box.readOnly=true;box.focus();
   let burst=0;
   for(const char of steps[i][0]){
    if(run.stopped||p?.id!==id)break;
    chatDraft+=char;box.value=chatDraft;box.scrollTop=box.scrollHeight;
    burst++;await pause(/[，。？]/.test(char)?180+Math.random()*260:burst%7===0?100+Math.random()*180:16+Math.random()*45);
   }
   if(run.stopped||p?.id!==id)break;
   run.phase='检查输入';const hint=$('.demo-phase');if(hint)hint.textContent=run.phase;await pause(300+Math.random()*400);
   if(run.stopped)break;
   run.phase='等待分析结果';await say(steps[i][0]);
   if(p.operation.status!=='complete')throw Error(p.operation.message||'本步骤未完成');
   if(i===2&&!run.stopped){
    view='plan';run.phase='补充实验条件';render();
    const rows=[...document.querySelectorAll('[data-plan-id]')];
    for(const row of rows){
     for(const [field,text] of [['condition','沿用历史数据的40点用量网格'],['note','比较相对发光Q，记录完整响应曲线']]){
      const input=row.querySelector('[data-field="'+field+'"]');input.focus();input.scrollIntoView({behavior:'smooth',block:'nearest'});input.value='';
      for(const char of text){if(run.stopped)break;input.value+=char;await pause(12+Math.random()*22);}
      if(run.stopped)break;
     }
     if(run.stopped)break;
    }
    if(!run.stopped)await act('save_plan',{items:readRows('[data-plan-id]'),notes:'按公开历史数据条件演示实验安排；实测结果来自历史记录。'},'plan');
   }
   if(i===5&&!run.stopped){
    run.phase='打开研究报告';render();
    const reportButton=document.querySelector('[data-view="report"]');
    if(reportButton&&!reducedMotion())reportButton.animate([{background:'#d5d7dd',transform:'scale(1)'},{background:'#c4cfdf',transform:'scale(.97)'},{background:'#d5d7dd',transform:'scale(1)'}],{duration:450});
    await pause(700);
    if(run.stopped)break;
   }
   if(i===5&&!run.stopped)localStorage.setItem('amadeus-report-'+id,'ready');
   run.completed=i+1;run.phase='查看'+['候选排序','更新后的名单','已保存计划','历史实测','下一轮建议','研究报告'][i];view=steps[i][1];render();
   await pause(900);
   const pane=$('.workspace-body');
   if(pane&&!run.stopped){
    const distance=pane.scrollHeight-pane.clientHeight;
    for(let y=Math.min(420,distance);distance>0&&y<=distance&&!run.stopped;y=Math.min(y+420,distance)){
     pane.scrollTo({top:y,behavior:reducedMotion()?'instant':'smooth'});await pause(i===5?2200:1600);
     if(y===distance)break;
    }
    if(!run.stopped){pane.scrollTo({top:0,behavior:reducedMotion()?'instant':'smooth'});await pause(800);}
   }
   await pause([1500,1200,1000,2200,1500,1500][i]);
  }
  if(!run.stopped)toast('演示完成，研究报告和项目记录已保存。');
 }catch(e){toast(e.message);}finally{if(autoDemo===run)autoDemo=null;render();}
}
async function stopDemo(){
 if(!autoDemo)return;autoDemo.stopped=true;
 if(running())await api('/api/projects/'+p.id+'/cancel',{});
 toast('已停止演示，已完成的内容保留在项目中。');
}
function readRows(selector){return [...document.querySelectorAll(selector)].map(tr=>{const row={};for(const el of tr.querySelectorAll('[data-field]'))row[el.dataset.field]=el.value;return {...row,candidate_id:tr.dataset.planId||tr.dataset.resultId,name:tr.dataset.name,condition:row.condition??tr.dataset.condition};});}
document.addEventListener('input',e=>{if(e.target.id==='chat-input')chatDraft=e.target.value;});
document.addEventListener('keydown',e=>{if(e.target.id==='chat-input'&&e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();$('#chat-form').requestSubmit();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-view]');if(!b||b.disabled)return;try{
 if(b.dataset.do==='stop-demo'){await stopDemo();return;}
 if(autoDemo){toast('演示正在进行，点击停止演示即可接手。');return;}
 if(b.dataset.view){view=b.dataset.view;render();return;}
 if(b.dataset.case){const c=researchCases[b.dataset.case];await newProject(c.goal,c.title);await act('material_example',{example:b.dataset.case,replay:true},'overview');return;}
 if(b.dataset.project){await openProject(b.dataset.project);return;}
 if(b.dataset.say){await say(b.dataset.say);return;}
 if(b.dataset.detail){selectedDetail=b.dataset.detail;render();return;}
 if(b.dataset.exclude){await act('adjust',{exclude:[b.dataset.exclude]});return;}
 if(b.dataset.restore){await act('adjust',{restore:[b.dataset.restore]});return;}
 switch(b.dataset.do){case 'guide-save-plan':$('#plan-form').requestSubmit();break;
 case 'choose-material':await act('material_example',{example:$('#research-example').value,replay:true},'overview');break;
 case 'engine-project':await newProject('根据组成与实验条件筛选材料候选','材料条件建模');await act('material_example',{},'engine');break;
 case 'steels-project':await newProject('根据化学组成筛选高屈服强度钢合金','钢合金屈服强度');await act('material_example',{example:'steels'},'engine');break;
 case 'steels-example':await act('material_example',{example:'steels'},'engine');break;
 case 'material-example':await act('material_example',{},'engine');break;
 case 'auto-demo':await playDemo();break;
 case 'home':p=null;history.replaceState(null,'',location.pathname);await refreshList();render();break;
 case 'example':await newProject('提高 CsPbBr₃ 纳米晶的发光表现，这一轮优先测试3种配体。','纳米晶发光优化');await act('specialist');break;
 case 'example-here':await act('specialist');break;
 case 'csv-project':await newProject('根据历史实验数据预测候选表现，安排下一轮测试。','实验数据建模');view='data';render();break;
 case 'literature-project':await newProject('','研究资料与实验设计');break;
 case 'sample-csv':await sample();break;
 case 'history-results':await act('history_results',{},'results');break;
 case 'next-round':await act('next_round',{},'overview');break;
 case 'retrain':await act('train',{},'overview');break;
 case 'cancel':await api('/api/projects/'+p.id+'/cancel',{});toast('已请求停止。');break;
 case 'dismiss-error':p.operation.status='idle';render();break;}
 }catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{try{if(e.target.dataset.upload){const f=e.target.files[0];if(f){const text=await f.text();await act('upload',{kind:e.target.dataset.upload,text,filename:f.name});}}
 if(e.target.dataset.actionId){await act('select_actions',{ids:[...document.querySelectorAll('[data-action-id]:checked')].map(x=>x.dataset.actionId)});}
 if(['map-target','map-id','map-group'].includes(e.target.id)){const blocked=[$('#map-target').value,$('#map-id').value,$('#map-group').value];document.querySelectorAll('[name=feature]').forEach(x=>{if(blocked.includes(x.value))x.checked=false;});}
 }catch(err){toast(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();if(autoDemo)return;try{if(e.target.classList.contains('accept-form')){await act('accept_extraction',{draft_id:e.target.dataset.draftId,kind:e.target.elements.kind.value,records:JSON.parse(e.target.elements.records.value)},'engine');return;}switch(e.target.id){case 'new-form':{const goal=$('#new-goal').value.trim();if(!goal){toast('先描述一下研究问题。');return;}await newProject(goal,goal.slice(0,24));await say(goal);break;}
 case 'extract-form':{const file=$('#extract-pdf').files[0];let text=$('#extract-text').value,format='text',filename=$('#extract-name').value;if(file){const bytes=new Uint8Array(await file.arrayBuffer());text=btoa(Array.from(bytes,b=>String.fromCharCode(b)).join(''));format='pdf';filename=file.name;}await act('extract',{text,filename,format},'engine');break;}
 case 'process-form':await act('process',{kind:$('#process-kind').value,rules:JSON.parse($('#process-rules').value||'[]'),structure_column:$('#process-structure').value||null},'engine');break;
 case 'engine-train-form':await act('train',{mapping:{...JSON.parse($('#engine-config').value),optimize:$('#engine-optimize').checked,search_trials:Number($('#engine-trials').value),selection_metric:$('#engine-metric').value}},'engine');break;
 case 'chat-form':await say($('#chat-input').value);break;
 case 'task-form':await act('task',{goal:$('#task-goal').value,budget:Number($('#task-budget').value)});break;
 case 'train-form':{const mapping={target:$('#map-target').value,id:$('#map-id').value,task:$('#map-task').value,direction:$('#map-direction').value,group:$('#map-group').value,unit:$('#map-unit').value,positive:$('#map-positive').value,features:[...document.querySelectorAll('[name=feature]:checked')].map(x=>x.value)};await act('train',{mapping},'overview');break;}
 case 'plan-form':await act('save_plan',{items:readRows('[data-plan-id]'),notes:$('#plan-notes').value},'plan');break;
 case 'results-form':{const records=readRows('[data-result-id]').filter(r=>r.value!==''||r.note.trim()||r.status==='failed');if(!records.length){toast('先填写测量值或结果说明。');return;}await act('record',{records},'results');break;}}
 }catch(err){toast(err.message);}});
document.addEventListener('click',e=>{
 const link=e.target.closest('a[href^="/api/projects/"]');if(!link||(!window.AmadeusDemo&&!(p&&projectContext()&&link.getAttribute('href').endsWith('/report'))))return;
 e.preventDefault();if(!p)return;
 const type=link.getAttribute('href').split('/').at(-1);
 if(type==='report'){
  if(localStorage.getItem('amadeus-report-'+p.id)==='pending'){toast('报告正在整理，最后一步完成后即可打开。');return;}
  const win=window.open('','_blank');if(!win){toast('请允许打开报告窗口。');return;}
  win.document.write('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>Amadeus · 研究报告</title><base href="'+new URL('./',location.href).href+'"><link rel="stylesheet" href="'+new URL('./workbench.css',location.href).href+'"><style>body{display:block;padding:32px;max-width:1100px;margin:auto}.btn-row{display:none}h1{margin:20px 0}figure{break-inside:avoid}@media print{.print-button{display:none}body{padding:0}.sheet{break-inside:auto}}</style></head><body><button class="btn primary print-button" onclick="print()">保存 PDF / 打印</button>'+reportView()+'</body></html>');win.document.close();return;
 }
 let text, mime, name;
 if(type==='csv'){const items=plan()?.items||p.plans.at(-1)?.items||[];const keys=['candidate_id','name','condition','metric','unit','note'];const q=x=>'"'+String(x??'').replaceAll('"','""')+'"';text='\ufeff'+[keys,...items.map(i=>keys.map(k=>i[k]))].map(r=>r.map(q).join(',')).join('\r\n');mime='text/csv;charset=utf-8';name='Amadeus-plan.csv';}
 else{text=JSON.stringify(p,null,2);mime='application/json';name='Amadeus-project.json';}
 const url=URL.createObjectURL(new Blob([text],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);
});
async function boot(){try{researchCases=await fetch('./research-cases.json').then(r=>r.json());if(location.protocol!=='file:'){const cfg=await api('/api/config');local=cfg.local;configured=cfg.configured;await refreshList();}}catch{local=false;}if(local&&location.hash.slice(1)){try{await openProject(location.hash.slice(1));return;}catch{history.replaceState(null,'',location.pathname);}}render();}
boot();
})();
